"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["63225"],{69188(e){e.exports=JSON.parse('{"id":"F439","slug":"reserve-adequacy","name":"Reserve Adequacy Metrics","subject":"International Finance","section":"Global Finance","topic":"Exchange rate regimes","level":"Intermediate","aliases":["exchange rate regimes","foreign exchange reserves","Greenspan-Guidotti","IMF ARA metric","import cover"],"formula":{"latex":"\\\\text{Import cover}=\\\\frac{12\\\\,R}{\\\\text{Imports}},\\\\quad \\\\frac{R}{STD}\\\\ge1,\\\\quad ARA=0.05X+0.05M2+0.30\\\\,STD+0.15\\\\,OL","also":[],"text":"Import cover (months) = reserves / (annual imports / 12); Short-term debt cover = reserves / short-term external debt (Greenspan-Guidotti: at least 1); IMF reserve adequacy metric (fixed exchange rate) = 5% of exports + 5% of broad money + 30% of short-term debt + 15% of other liabilities (weights for a fixed regime; floating regimes use lower ones)"},"symbols":[{"symbol":"R","meaning":"Foreign exchange reserves","unit":"money"},{"symbol":"STD","meaning":"External debt due within one year","unit":"money"},{"symbol":"M2","meaning":"Broad money","unit":"money"},{"symbol":"OL","meaning":"Other external portfolio liabilities","unit":"money"},{"symbol":"X","meaning":"Annual exports","unit":"money"}],"when_to_use":"Use it to judge whether a country can defend its exchange rate regime. A peg or tightly managed rate needs reserves to meet capital outflows and pay for imports; a floating rate needs less. Three common tests are months of imports covered, cover for short-term debt, and the IMF composite metric (a ratio of 100% to 150% of the metric is regarded as adequate). The weights shown are the fixed-regime weights, and the IMF publishes different ones for other regimes.","worked_example":{"problem":"Reserves are 180 billion, imports 600, exports 400, broad money 700, short-term external debt 90 and other external liabilities 150 (billions).","inputs":{"r":180,"imp":600,"x":400,"m2":700,"std":90,"ol":150},"steps":[{"label":"Import cover in months","working":"180 / (600 / 12)","value":"3.6"},{"label":"Short-term debt cover","working":"180 / 90","value":"2.00"},{"label":"IMF metric (fixed regime) = 5% X + 5% M2 + 30% STD + 15% OL","working":"0.05 x 400+0.05 x 700+0.30 x 90+0.15 x 150","value":"104.5"},{"label":"Reserves / IMF metric","working":"180 / 104.5","value":"172%"}],"answer":"Reserves cover 3.6 months of imports and 2.00 times short-term debt, which passes the rule of 1. The IMF metric comes to 104.5, so reserves are 172% of it, above the 100% level."},"calculator":{"available":true,"inputs":[{"id":"r","label":"Reserves","unit":"billions","type":"number","default":180,"hint":""},{"id":"imp","label":"Annual imports","unit":"billions","type":"number","default":600,"hint":""},{"id":"x","label":"Annual exports","unit":"billions","type":"number","default":400,"hint":""},{"id":"m2","label":"Broad money","unit":"billions","type":"number","default":700,"hint":""},{"id":"std","label":"Short-term external debt","unit":"billions","type":"number","default":90,"hint":""},{"id":"ol","label":"Other external liabilities","unit":"billions","type":"number","default":150,"hint":""}],"checks":[{"expr":"imp>0 and std>0","message":"Imports and short-term debt must be above zero."}],"steps":[{"id":"cover","label":"Import cover in months","expr":"r/(imp/12)","format":"num1"},{"id":"stdc","label":"Short-term debt cover","expr":"r/std","format":"num2"},{"id":"ara","label":"IMF metric (fixed regime) = 5% X + 5% M2 + 30% STD + 15% OL","expr":"0.05*x+0.05*m2+0.30*std+0.15*ol","format":"num1"},{"id":"ratio","label":"Reserves / IMF metric","expr":"r/ara","format":"pct0"}],"results":["cover","stdc","ara","ratio"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"cover":3.6,"stdc":2,"ara":104.5,"ratio":1.722488038277512}},"finder":{"finds":"Whether reserves are large enough for the exchange rate regime","needs":"Reserves, imports, exports, money, short-term debt, other liabilities"},"related":[{"slug":"urr-implicit-tax","name":"Capital Controls: Reserve Requirement Implicit Tax"},{"slug":"balance-of-payments-identity","name":"Balance of Payments Identity"},{"slug":"debt-dynamics","name":"Government Debt Dynamics"}],"related_ids":["F440","F447","F090"],"group":"Money, banks and the economy","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Import\xa0cover</mtext><mo>=</mo><mfrac><mrow><mn>12</mn><mtext>\u2009</mtext><mi>R</mi></mrow><mtext>Imports</mtext></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mfrac><mi>R</mi><mrow><mi>S</mi><mi>T</mi><mi>D</mi></mrow></mfrac><mo>\u2265</mo><mn>1</mn><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>A</mi><mi>R</mi><mi>A</mi><mo>=</mo><mn>0.05</mn><mi>X</mi><mo>+</mo><mn>0.05</mn><mi>M</mi><mn>2</mn><mo>+</mo><mn>0.30</mn><mtext>\u2009</mtext><mi>S</mi><mi>T</mi><mi>D</mi><mo>+</mo><mn>0.15</mn><mtext>\u2009</mtext><mi>O</mi><mi>L</mi></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Import cover}=\\\\frac{12\\\\,R}{\\\\text{Imports}},\\\\quad \\\\frac{R}{STD}\\\\ge1,\\\\quad ARA=0.05X+0.05M2+0.30\\\\,STD+0.15\\\\,OL</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"repricing-gap","name":"Repricing Gap and Net Interest Income"},"next":{"slug":"reserve-requirement-cost-of-funds","name":"Reserve Requirement Wedge and Offshore Deposit Rates"},"lesson":null,"total":522}')}}]);